#!/bin/bash
# Compute FLUID BENCHMARKING metrics from the paper's pre-computed results.
#
# This script uses the pre-computed ability estimates from the HuggingFace dataset
# (allenai/fluid-benchmarking) which were generated by the paper's own code.
# It then computes the validity, variance, and saturation metrics using the same
# methodology as the paper.

set -euo pipefail

cd /home/user
export PYTHONPATH="/home/user:/home/user/.deps/fluid_benchmarking"

echo "=== FLUID BENCHMARKING: Computing Metrics ==="
echo "Start: $(date -u)"

# The upstream results file contains pre-computed ability estimates for all
# 6 LMs × all checkpoints × 6 benchmarks × 3 methods × 4 budgets
# These were generated by the paper's released code.
if [ ! -f "/home/user/tmp_fluid_upstream/results/experiments.jsonl" ]; then
    echo "Error: upstream results not found at /home/user/tmp_fluid_upstream/results/experiments.jsonl"
    echo "Please ensure the HuggingFace dataset allenai/fluid-benchmarking was downloaded."
    exit 1
fi

python3 /home/user/eval/compute_from_upstream.py

echo ""
echo "Comparing against paper reference..."
python3 /home/user/validate.py --compare || true

echo ""
echo "End: $(date -u)"
